function lbs(arr) {
  const n = arr.length;
  const lis = new Array(n).fill(1);
  for (let i = 1; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && lis[i] < lis[j] + 1) {
        lis[i] = lis[j] + 1;
      }
    }
  }
  const lds = new Array(n).fill(1);
  for (let i = n - 2; i >= 0; i--) {
    for (let j = n - 1; j > i; j--) {
      if (arr[i] > arr[j] && lds[i] < lds[j] + 1) {
        lds[i] = lds[j] + 1;
      }
    }
  }
  let maximum = lis[0] + lds[0] - 1;
  for (let i = 1; i < n; i++) {
    maximum = Math.max(lis[i] + lds[i] - 1, maximum);
  }
  return maximum;
}

function isSublist(l, s) {
  let subSet = false;
  if (s.length === 0) {
    subSet = true;
  } else if (s.length === l.length && l.every((v, i) => v === s[i])) {
    subSet = true;
  } else if (s.length > l.length) {
    subSet = false;
  } else {
    for (let i = 0; i < l.length; i++) {
      if (l[i] === s[0]) {
        let n = 1;
        while (n < s.length && l[i + n] === s[n]) {
          n++;
        }
        if (n === s.length) {
          subSet = true;
        }
      }
    }
  }
  return subSet;
}

function mergeSortedList(num1, num2, num3) {
  num1 = num1.slice().sort((a, b) => a - b);
  num2 = num2.slice().sort((a, b) => a - b);
  num3 = num3.slice().sort((a, b) => a - b);
  const result = [];
  let i = 0, j = 0, k = 0;
  while (i < num1.length || j < num2.length || k < num3.length) {
    const candidates = [];
    if (i < num1.length) candidates.push({ val: num1[i], idx: 'i' });
    if (j < num2.length) candidates.push({ val: num2[j], idx: 'j' });
    if (k < num3.length) candidates.push({ val: num3[k], idx: 'k' });
    const min = candidates.reduce((prev, curr) => curr.val < prev.val ? curr : prev);
    result.push(min.val);
    if (min.idx === 'i') i++;
    else if (min.idx === 'j') j++;
    else k++;
  }
  return result;
}

