  for (let i = 1; i < testStr.length - 1; i++) {
    if (
      !vowels.includes(testStr[i]) &&
      (vowels.includes(testStr[i - 1]) || vowels.includes(testStr[i + 1]))
    ) {
      res++;
    }
  }
  if (!vowels.includes(testStr[0]) && vowels.includes(testStr[1])) {
    res++;
  }
  if (
    !vowels.includes(testStr[testStr.length - 1]) &&
    vowels.includes(testStr[testStr.length - 2])
  ) {
    res++;
  }
  return res;
}

function modularSum(arr, n, m) {
    if (n > m) return true;
    const DP = new Array(m).fill(false);
    for (let i = 0; i < n; i++) {
        if (DP[0]) return true;
        const temp = new Array(m).fill(false);
        for (let j = 0; j < m; j++) {
            if (DP[j] && !DP[(j + arr[i]) % m]) {
                temp[(j + arr[i]) % m] = true;
            }
        }
        for (let j = 0; j < m; j++) {
            if (temp[j]) {
                DP[j] = true;
            }
        }
        DP[arr[i] % m] = true;
    }
    return DP[0];
}

function minSwaps(s1, s2) {
    let c0 = 0;
    let c1 = 0;
    for (let i = 0; i < s1.length; i++) {
        if (s1[i] === '0' && s2[i] === '1') {
            c0++;
        } else if (s1[i] === '1' && s2[i] === '0') {
            c1++;
        }
    }
    const result = Math.floor(c0 / 2) + Math.floor(c1 / 2);
    if (c0 % 2 === 0 && c1 % 2 === 0) {
        return result;
    } else if ((c0 + c1) % 2 === 0) {
        return result + 2;
    } else {
        return -1;
    }
}

function getMaxGold(gold, m, n) {
    const goldTable = Array.from({ length: m }, () => Array(n).fill(0));
    for (let col = n - 1; col >= 0; col--) {
        for (let row = 0; row < m; row++) {
            const right = (col === n - 1) ? 0 : goldTable[row][col + 1];
            const rightUp = (row === 0 || col === n - 1) ? 0 : goldTable[row - 1][col + 1];
            const rightDown = (row === m - 1 || col === n - 1) ? 0 : goldTable[row + 1][col + 1];
            goldTable[row][col] = gold[row][col] + Math.max(right, rightUp, rightDown);
        }
    }
    let res = goldTable[0][0];
    for (let i = 1; i < m; i++) {
        res = Math.max(res, goldTable[i][0]);
    }
    return res;
}

function heapSort(arr) {
    heapify(arr);
    let end = arr.length - 1;
    while (end > 0) {
        [arr[end], arr[0]] = [arr[0], arr[end]];
        shiftDown(arr, 0, end - 1);
        end--;
    }
    return arr;
}

function heapify(arr) {
    let start = Math.floor(arr.length / 2);
    while (start >= 0) {
        shiftDown(arr, start, arr.length - 1);
        start--;
    }
}

function shiftDown(arr, start, end) {
    let root = start;
    while (root * 2 + 1 <= end) {
        let child = root * 2 + 1;
        if (child + 1 <= end && arr[child] < arr[child + 1]) {
            child++;
        }
        if (child <= end && arr[root] < arr[child]) {
            [arr[root], arr[child]] = [arr[child], arr[root]];
            root = child;
        } else {
            return;
        }
    }
}

function find_Max_Len_Even(str) {
    let n = str.length;
    let i = 0;
    let currlen = 0;
    let maxlen = 0;
    let st = -1;
    while (i < n) {
        if (str[i] === ' ') {
            if (currlen % 2 === 0) {
                if (maxlen < currlen) {
                    maxlen = currlen;
                    st = i - currlen;
                }
            }
            currlen = 0;
        } else {
            currlen++;
        }
        i++;
    }
    if (currlen % 2 === 0) {
        if (maxlen < currlen) {
            maxlen = currlen;
            st = i - currlen;
        }
    }
    if (st === -1) {
        return "-1";
    }
    return str.substring(st, st + maxlen);
}

function isSamePatterns(colors, patterns) {
    if (colors.length !== patterns.length) {
        return false;
    }
    const sdict = {};
    const pset = new Set();
    const sset = new Set();
    for (let i = 0; i < patterns.length; i++) {
        pset.add(patterns[i]);
        sset.add(colors[i]);
        const key = patterns[i];
        if (!sdict[key]) {
            sdict[key] = [];
        }
        sdict[key].push(colors[i]);
    }
    if (pset.size !== sset.size) {
        return false;
    }
    for (const values of Object.values(sdict)) {
        for (let i = 0; i < values.length - 1; i++) {
            if (values[i] !== values[i + 1]) {
                return false;
            }
        }
    }
    return true;
}

function generateMatrix(n) {
    if (n <= 0) {
        return [];
    }
    const matrix = Array.from({ length: n }, () => Array(n).fill(0));
    let rowSt = 0, rowEd = n - 1, colSt = 0, colEd = n - 1, current = 1;
    const max = n * n;
    while (true) {
        if (current > max) break;
        for (let c = colSt; c <= colEd; c++) {
            matrix[rowSt][c] = current++;
        }
        rowSt++;
        for (let r = rowSt; r <= rowEd; r++) {
            matrix[r][colEd] = current++;
        }
        colEd--;
        for (let c = colEd; c >= colSt; c--) {
            matrix[rowEd][c] = current++;
        }
        rowEd--;
        for (let r = rowEd; r >= rowSt; r--) {
            matrix[r][colSt] = current++;
        }
        colSt++;
    }
    return matrix;
}

function ngcd(x, y) {
    let i = 1;
    let gcd = 1;
    while (i <= x && i <= y) {
        if (x % i === 0 && y % i === 0) {
            gcd = i;
        }
        i += 1;
    }
    return gcd;
}

function num_comm_div(x, y) {
    const n = ngcd(x, y);
    let result = 0;
    const z = Math.floor(Math.sqrt(n));
    let i = 1;
    while (i <= z) {
        if (n % i === 0) {
            result += 2;
            if (i === n / i) {
                result -= 1;
            }
        }
        i += 1;
    }
    return result;
}

function findClosest(A, B, C, p, q, r) {
    let diff = Number.MAX_SAFE_INTEGER;
    let res_i = 0, res_j = 0, res_k = 0;
    let i = 0, j = 0, k = 0;
    while (i < p && j < q && k < r) {
        const minimum = Math.min(A[i], B[j], C[k]);
        const maximum = Math.max(A[i], B[j], C[k]);
        if (maximum - minimum < diff) {
            res_i = i;
            res_j = j;
            res_k = k;
            diff = maximum - minimum;
        }
        if (diff === 0) {
            break;
        }
        if (A[i] === minimum) {
            i++;
        } else if (B[j] === minimum) {
            j++;
        } else {
            k++;
        }
    }
    return [A[res_i], B[res_j], C[res_k]];
}

function maxSumIncreasingSubseq(a, n, index, k) {
    const dp = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        if (a[i] > a[0]) {
            dp[0][i] = a[i] + a[0];
        } else {
            dp[0][i] = a[i];
        }
    }
    for (let i = 1; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (a[j] > a[i] && j > i) {
                if (dp[i - 1][i] + a[j] > dp[i - 1][j]) {
                    dp[i][j] = dp[i - 1][i] + a[j];
                } else {
                    dp[i][j] = dp[i - 1][j];
                }
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }
    return dp[index][k];
}

function maxSumIncreasingSubsequence(arr, n) {
    let max = 0;
    const msis = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        msis[i] = arr[i];
    }
    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] > arr[j] && msis[i] < msis[j] + arr[i]) {
                msis[i] = msis[j] + arr[i];
            }
        }
    }
    for (let i = 0; i < n; i++) {
        if (max < msis[i]) {
            max = msis[i];
        }
    }
    return max;
}

function findMax(arr, low, high) {
    if (high < low) {
        return arr[0];
    }
    if (high === low) {
        return arr[low];
    }
    const mid = low + Math.floor((high - low) / 2);
    if (mid < high && arr[mid + 1] < arr[mid]) {
        return arr[mid];
    }
    if (mid > low && arr[mid] < arr[mid - 1]) {
        return arr[mid - 1];
    }
    if (arr[low] > arr[mid]) {
        return findMax(arr, low, mid - 1);
    } else {
        return findMax(arr, mid + 1, high);
    }
}

function smallestMultiple(n) {
    if (n <= 2) return n;
    let i = n * 2;
    const factors = [];
    for (let number = n; number > 1; number--) {
        if (number * 2 > n) factors.push(number);
    }
    while (true) {
        for (let a of factors) {
            if (i % a !== 0) {
                i += n;
                break;
            }
            if (a === factors[factors.length - 1]) {
                return i;
            }
        }
    }
}

function binomialCoeff(n, k) {
    if (k === 0 || k === n) {
        return 1;
    }
    return binomialCoeff(n - 1, k - 1) + binomialCoeff(n - 1, k);
}

function rencontresNumber(n, m) {
    if (n === 0 && m === 0) {
        return 1;
    }
    if (n === 1 && m === 0) {
        return 0;
    }
    if (m === 0) {
        return (n - 1) * (rencontresNumber(n - 1, 0) + rencontresNumber(n - 2, 0));
    }
    return binomialCoeff(n, m) * rencontresNumber(n - m, 0);
}

function checkIdentical(list1, list2) {
