    if (!Array.isArray(tuple1) || !Array.isArray(tuple2) || tuple1.length !== tuple2.length) {
      return false;
    }
    for (let j = 0; j < tuple1.length; j++) {
      if (tuple1[j] !== tuple2[j]) {
        return false;
      }
    }
  }
  return true;
}

