    }
}

function maxSubarrayProduct(arr) {
  let n = arr.length;
  let maxEndingHere = 1;
  let minEndingHere = 1;
  let maxSoFar = 0;
  let flag = 0;
  for (let i = 0; i < n; i++) {
    if (arr[i] > 0) {
      maxEndingHere = maxEndingHere * arr[i];
      minEndingHere = Math.min(minEndingHere * arr[i], 1);
      flag = 1;
    } else if (arr[i] === 0) {
      maxEndingHere = 1;
      minEndingHere = 1;
    } else {
      let temp = maxEndingHere;
      maxEndingHere = Math.max(minEndingHere * arr[i], 1);
      minEndingHere = temp * arr[i];
    }
    if (maxSoFar < maxEndingHere) {
      maxSoFar = maxEndingHere;
    }
  }
  if (flag === 0 && maxSoFar === 0) {
    return 0;
  }
  return maxSoFar;
}

function sumofFactors(n) {
    if (n % 2 !== 0) return 0;
    let res = 1;
    const limit = Math.floor(Math.sqrt(n));
    for (let i = 2; i <= limit; i++) {
        let count = 0;
        let curr_sum = 1;
        let curr_term = 1;
        while (n % i === 0) {
            count++;
            n = n / i;
            if (i === 2 && count === 1) {
                curr_sum = 0;
            }
            curr_term *= i;
            curr_sum += curr_term;
        }
        res *= curr_sum;
    }
    if (n >= 2) {
        res *= (1 + n);
    }
    return res;
}

function maxProfit(price, k) {
    const n = price.length;
    const finalProfit = Array.from({ length: k + 1 }, () => Array(n).fill(null));
    for (let i = 0; i <= k; i++) {
        for (let j = 0; j < n; j++) {
            if (i === 0 || j === 0) {
                finalProfit[i][j] = 0;
            } else {
                let maxSoFar = 0;
                for (let x = 0; x < j; x++) {
                    const currPrice = price[j] - price[x] + finalProfit[i - 1][x];
                    if (maxSoFar < currPrice) {
                        maxSoFar = currPrice;
                    }
                }
                finalProfit[i][j] = Math.max(finalProfit[i][j - 1], maxSoFar);
            }
        }
    }
    return finalProfit[k][n - 1];
}

function lps(s) {
    const n = s.length;
    const L = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        L[i][i] = 1;
    }
    for (let cl = 2; cl <= n; cl++) {
        for (let i = 0; i < n - cl + 1; i++) {
            const j = i + cl - 1;
            if (s[i] === s[j] && cl === 2) {
                L[i][j] = 2;
            } else if (s[i] === s[j]) {
                L[i][j] = L[i + 1][j - 1] + 2;
            } else {
                L[i][j] = Math.max(L[i][j - 1], L[i + 1][j]);
            }
        }
    }
    return L[0][n - 1];
}

function findRotationCount(A) {
    let left = 0;
    let right = A.length - 1;
    while (left <= right) {
        if (A[left] <= A[right]) {
            return left;
        }
        let mid = Math.floor((left + right) / 2);
        let next = (mid + 1) % A.length;
        let prev = (mid - 1 + A.length) % A.length;
        if (A[mid] <= A[next] && A[mid] <= A[prev]) {
            return mid;
        } else if (A[mid] <= A[right]) {
            right = mid - 1;
        } else if (A[mid] >= A[left]) {
            left = mid + 1;
        }
    }
    return -1;
}

function rawHeap(arr) {
  const n = arr.length
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
    siftDown(arr, i, n)
  }
  return arr
}

function siftDown(arr, i, n) {
  while (true) {
    let left = 2 * i + 1
    if (left >= n) break
    let right = left + 1
    let j = right < n && arr[right] < arr[left] ? right : left
    if (arr[j] < arr[i]) {
      [arr[i], arr[j]] = [arr[j], arr[i]]
      i = j
    } else break
  }
}

function secondSmallest(numbers) {
  if (!Array.isArray(numbers) || numbers.length < 2) {
    return;
  }
  if (numbers.length === 2 && numbers[0] === numbers[1]) {
    return;
  }
  const dupItems = new Set();
  const uniqItems = [];
  for (const x of numbers) {
    if (!dupItems.has(x)) {
      uniqItems.push(x);
      dupItems.add(x);
    }
  }
  uniqItems.sort((a, b) => a - b);
  return uniqItems[1];
}

function maxLenSub(arr, n) {
