    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (Math.abs(arr[i] - arr[j]) <= 1 && mls[i] < mls[j] + 1) {
                mls[i] = mls[j] + 1;
            }
        }
    }
    for (let i = 0; i < n; i++) {
        if (max < mls[i]) {
            max = mls[i];
        }
    }
    return max;
}

function countHexadecimal(L, R) {
  let count = 0;
  for (let i = L; i <= R; i++) {
    if (i >= 10 && i <= 15) {
      count++;
    } else if (i > 15) {
      let k = i;
      while (k !== 0) {
        if (k % 16 >= 10) {
          count++;
        }
        k = Math.floor(k / 16);
      }
    }
  }
  return count;
}

function longestSubseqWithDiffOne(arr, n) {
    const dp = Array(n).fill(1);
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] === arr[j] + 1 || arr[i] === arr[j] - 1) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
    }
    let result = 1;
    for (let i = 0; i < n; i++) {
        if (result < dp[i]) {
            result = dp[i];
        }
    }
    return result;
}

function getTotalNumberOfSequences(m, n) {
    const T = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    for (let i = 0; i <= m; i++) {
        for (let j = 0; j <= n; j++) {
            if (i === 0 || j === 0) {
                T[i][j] = 0;
            } else if (i < j) {
                T[i][j] = 0;
            } else if (j === 1) {
                T[i][j] = i;
            } else {
                T[i][j] = T[i - 1][j] + T[Math.floor(i / 2)][j - 1];
            }
        }
    }
    return T[m][n];
}

function minJumps(arr, n) {
    const jumps = new Array(n).fill(0);
    if (n === 0 || arr[0] === 0) {
        return Infinity;
    }
    jumps[0] = 0;
    for (let i = 1; i < n; i++) {
        jumps[i] = Infinity;
        for (let j = 0; j < i; j++) {
            if (i <= j + arr[j] && jumps[j] !== Infinity) {
                jumps[i] = Math.min(jumps[i], jumps[j] + 1);
                break;
            }
        }
    }
    return jumps[n - 1];
}

function findPeakUtil(arr, low, high, n) {
    const mid = low + Math.floor((high - low) / 2);
    if ((mid === 0 || arr[mid - 1] <= arr[mid]) &&
        (mid === n - 1 || arr[mid + 1] <= arr[mid])) {
        return mid;
    } else if (mid > 0 && arr[mid - 1] > arr[mid]) {
        return findPeakUtil(arr, low, mid - 1, n);
    } else {
        return findPeakUtil(arr, mid + 1, high, n);
    }
}

function findPeak(arr, n) {
    return findPeakUtil(arr, 0, n - 1, n);
}

function checkTypeOfTriangle(a, b, c) {
  const sqa = Math.pow(a, 2);
  const sqb = Math.pow(b, 2);
  const sqc = Math.pow(c, 2);
  if (sqa === sqa + sqb || sqb === sqa + sqc || sqc === sqa + sqb) {
    return "Right-angled Triangle";
  } else if (sqa > sqc + sqb || sqb > sqa + sqc || sqc > sqa + sqb) {
    return "Obtuse-angled Triangle";
  } else {
    return "Acute-angled Triangle";
  }
}

function checkTriplet(A, n, sum, count) {
    if (count === 3 && sum === 0) {
        return true;
    }
    if (count === 3 || n === 0 || sum < 0) {
        return false;
    }
    return checkTriplet(A, n - 1, sum - A[n - 1], count + 1) ||
           checkTriplet(A, n - 1, sum, count);
}

