    for (let i = 0; i < myList.length; i++) {
        if (myList[i] > maxValue) {
            maxValue = myList[i];
        }
    }
    const buckets = new Array(maxValue + 1).fill(0);
    for (let num of myList) {
        buckets[num]++;
    }
    let index = 0;
    for (let j = 0; j <= maxValue; j++) {
        for (let count = 0; count < buckets[j]; count++) {
            myList[index++] = j;
        }
    }
    return myList;
}

function exchangeElements(arr) {
  const odd = [];
  const even = [];
  for (let i = 0; i < arr.length; i++) {
    if (i % 2 === 1) {
      odd.push(arr[i]);
    } else {
      even.push(arr[i]);
    }
  }
  const result = [];
  const maxLen = Math.max(odd.length, even.length);
  for (let i = 0; i < maxLen; i++) {
    result.push(i < odd.length ? odd[i] : null);
    result.push(i < even.length ? even[i] : null);
  }
  return result;
}

function maximumSegments(n, a, b, c) {
    const dp = Array(n + 10).fill(-1);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        if (dp[i] !== -1) {
            if (i + a <= n) {
                dp[i + a] = Math.max(dp[i] + 1, dp[i + a]);
            }
            if (i + b <= n) {
                dp[i + b] = Math.max(dp[i] + 1, dp[i + b]);
            }
            if (i + c <= n) {
                dp[i + c] = Math.max(dp[i] + 1, dp[i + c]);
            }
        }
    }
    return dp[n];
}

function sumOfPrimes(n) {
    const prime = new Array(n + 1).fill(true);
    let p = 2;
    while (p * p <= n) {
        if (prime[p]) {
            for (let i = p * 2; i <= n; i += p) {
                prime[i] = false;
            }
        }
        p++;
    }
    let sum = 0;
    for (let i = 2; i <= n; i++) {
        if (prime[i]) sum += i;
    }
    return sum;
}

function isIsomorphic(str1, str2) {
