    for (let i = 0; i < m; i++) {
        table[0][i] = 1;
    }
    for (let i = 1; i <= n; i++) {
        for (let j = 0; j < m; j++) {
            const x = i - S[j] >= 0 ? table[i - S[j]][j] : 0;
            const y = j >= 1 ? table[i][j - 1] : 0;
            table[i][j] = x + y;
        }
    }
    return table[n][m - 1];
}

function minCoins(coins, m, V) {
    if (V === 0) return 0;
    let res = Number.MAX_SAFE_INTEGER;
    for (let i = 0; i < m; i++) {
        if (coins[i] <= V) {
            const subRes = minCoins(coins, m, V - coins[i]);
            if (subRes !== Number.MAX_SAFE_INTEGER && subRes + 1 < res) {
                res = subRes + 1;
            }
        }
    }
    return res;
}

function checkMinHeap(arr, i = 0) {
