  for (let i = 0; i < n; i++) {
    const j = find_ind(arr[i], i, n, k, arr);
    if (j !== -1) {
      ans = Math.min(ans, n - (j - i + 1));
    }
  }
  return ans;
}

function calSum(n) {
    let a = 3;
    let b = 0;
    let c = 2;
    if (n === 0) {
        return 3;
    }
    if (n === 1) {
        return 3;
    }
    if (n === 2) {
        return 5;
    }
    let sum = 5;
    while (n > 2) {
