function radixSort(nums) {
  const RADIX = 10;
  let placement = 1;
  const maxDigit = Math.max(...nums);
  while (placement < maxDigit) {
    const buckets = Array.from({ length: RADIX }, () => []);
    for (let i = 0; i < nums.length; i++) {
      const tmp = Math.floor((nums[i] / placement) % RADIX);
      buckets[tmp].push(nums[i]);
    }
    let a = 0;
    for (let b = 0; b < RADIX; b++) {
      const buck = buckets[b];
      for (let i = 0; i < buck.length; i++) {
        nums[a++] = buck[i];
      }
    }
    placement *= RADIX;
  }
  return nums;
}

function findPlatform(arr, dep, n) {
    arr.sort((a, b) => a - b);
    dep.sort((a, b) => a - b);
    let platNeeded = 1;
    let result = 1;
    let i = 1;
    let j = 0;
    while (i < n && j < n) {
        if (arr[i] <= dep[j]) {
            platNeeded++;
            i++;
        } else {
            platNeeded--;
            j++;
        }
        if (platNeeded > result) {
            result = platNeeded;
        }
    }
    return result;
}

function sumOfOddFactors(n) {
    let res = 1;
    while (n % 2 === 0) {
        n /= 2;
    }
    const limit = Math.sqrt(n);
    for (let i = 3; i <= limit; i++) {
        let currSum = 1;
        let currTerm = 1;
        while (n % i === 0) {
            n /= i;
            currTerm *= i;
            currSum += currTerm;
        }
        res *= currSum;
    }
    if (n >= 2) {
        res *= (1 + n);
    }
    return res;
}

function swapCount(s) {
    let countLeft = 0;
    let countRight = 0;
    let swap = 0;
    let imbalance = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '[') {
            countLeft++;
            if (imbalance > 0) {
                swap += imbalance;
                imbalance--;
            }
        } else if (s[i] === ']') {
            countRight++;
            imbalance = countRight - countLeft;
        }
    }
    return swap;
}

function isWoodall(x) {
    if (x % 2 === 0) {
        return false;
    }
    if (x === 1) {
        return true;
    }
    let m = x + 1;
    let p = 0;
    while (m % 2 === 0) {
        m /= 2;
        p++;
        if (p === m) {
            return true;
        }
    }
    return false;
}

function maxPrimeFactors(n) {
    let maxPrime = -1;
    while (n % 2 === 0) {
        maxPrime = 2;
        n /= 2;
    }
    let limit = Math.sqrt(n);
    for (let i = 3; i <= limit; i += 2) {
        while (n % i === 0) {
            maxPrime = i;
            n /= i;
        }
    }
    if (n > 2) {
        maxPrime = n;
    }
    return Math.trunc(maxPrime);
}

const MAX = 3000;
function smartNumber(n) {
