    let count = 0;
    noOfZeroes[n - 1] = 1 - arr[n - 1];
    for (let i = n - 2; i >= 0; i--) {
        noOfZeroes[i] = noOfZeroes[i + 1];
        if (arr[i] === 0) {
            noOfZeroes[i]++;
        }
    }
    for (let i = 0; i < n; i++) {
        if (arr[i] === 1) {
            count += noOfZeroes[i];
        }
    }
    return count;
}

function minCost(cost, m, n) {
    const tc = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    tc[0][0] = cost[0][0];
    for (let i = 1; i <= m; i++) {
        tc[i][0] = tc[i - 1][0] + cost[i][0];
    }
    for (let j = 1; j <= n; j++) {
        tc[0][j] = tc[0][j - 1] + cost[0][j];
    }
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            tc[i][j] = Math.min(tc[i - 1][j - 1], tc[i - 1][j], tc[i][j - 1]) + cost[i][j];
        }
    }
    return tc[m][n];
}

function combSort(nums) {
    const shrinkFact = 1.3;
    let gaps = nums.length;
    let swapped = true;
    while (gaps > 1 || swapped) {
        gaps = Math.floor(gaps / shrinkFact);
        swapped = false;
        for (let i = 0; i + gaps < nums.length; i++) {
            if (nums[i] > nums[i + gaps]) {
                [nums[i], nums[i + gaps]] = [nums[i + gaps], nums[i]];
                swapped = true;
            }
        }
    }
    return nums;
}

function maxSum(tri, n) {
