    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            if (arr[i] === arr[j]) {
                cnt++;
            }
        }
    }
    return cnt;
}

function getInvCount(arr, n) {
    let invCount = 0;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            if (arr[i] > arr[j]) {
                invCount++;
            }
        }
    }
    return invCount;
}

function Sum(N) {
    const sumOfPrimeDivisors = new Array(N + 1).fill(0);
    for (let i = 2; i <= N; i++) {
        if (sumOfPrimeDivisors[i] === 0) {
            for (let j = i; j <= N; j += i) {
                sumOfPrimeDivisors[j] += i;
            }
        }
    }
    return sumOfPrimeDivisors[N];
}

function isTwoAlter(s) {
    for (let i = 0; i < s.length - 2; i++) {
        if (s[i] !== s[i + 2]) {
            return false;
        }
    }
    if (s[0] === s[1]) {
        return false;
    }
    return true;
}

function joinTuples(testList) {
  const res = [];
  for (const sub of testList) {
    if (res.length && res[res.length - 1][0] === sub[0]) {
      res[res.length - 1].push(...sub.slice(1));
    } else {
      res.push(sub.slice());
    }
  }
  return res;
}

function kthElement(arr, n, k) {
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n - i - 1; j++) {
      if (arr[j] > arr[j + 1]) {
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
      }
    }
  }
  return arr[k - 1];
}

function countSamePair(list1, list2, list3) {
  let result = 0;
  const length = Math.min(list1.length, list2.length, list3.length);
  for (let i = 0; i < length; i++) {
    if (list1[i] === list2[i] && list2[i] === list3[i]) {
      result++;
    }
  }
  return result;
}

function countCharPosition(str1) {
    let countChars = 0;
    for (let i = 0; i < str1.length; i++) {
        const code = str1.charCodeAt(i);
        if (i === code - 'A'.charCodeAt(0) || i === code - 'a'.charCodeAt(0)) {
            countChars++;
        }
    }
    return countChars;
}

function extractMinMax(testArr, K) {
  const res = [];
  const temp = [...testArr].sort((a, b) => a - b);
  for (let idx = 0; idx < temp.length; idx++) {
    if (idx < K || idx >= temp.length - K) {
      res.push(temp[idx]);
    }
  }
  return res;
}

function uniqueCharacters(str) {
    for (let i = 0; i < str.length; i++) {
        for (let j = i + 1; j < str.length; j++) {
            if (str[i] === str[j]) {
                return false;
            }
        }
    }
    return true;
}

function sumSquare(n) {
  for (let i = 1; i * i <= n; i++) {
    for (let j = 1; j * j <= n; j++) {
      if (i * i + j * j === n) {
        return true;
      }
    }
  }
  return false;
}

function isPerfectSquare(n) {
    let i = 1;
    while (i * i <= n) {
        if (n % i === 0 && n / i === i) {
            return true;
        }
        i++;
    }
    return false;
}

function addDict(d1, d2) {
  const result = {};
  for (const [key, value] of Object.entries(d1)) {
    result[key] = value;
  }
  for (const [key, value] of Object.entries(d2)) {
    result[key] = (result[key] || 0) + value;
  }
  return result;
}

function binomialCoeff(n, k) {
  if (k > n) {
    return 0;
  }
  if (k === 0 || k === n) {
    return 1;
  }
  return binomialCoeff(n - 1, k - 1) + binomialCoeff(n - 1, k);
}

function freqElement(nums) {
  const counts = {};
  for (const sub of nums) {
    for (const item of sub) {
      counts[item] = (counts[item] || 0) + 1;
    }
  }
  return counts;
}

function eulerianNum(n, m) {
    if (m >= n || n === 0) {
        return 0;
    }
    if (m === 0) {
        return 1;
    }
    return (n - m) * eulerianNum(n - 1, m - 1) + (m + 1) * eulerianNum(n - 1, m);
}

function sum(a, b) {
  let sum = 0;
  for (let i = 1; i < Math.min(a, b); i++) {
    if (a % i === 0 && b % i === 0) {
      sum += i;
    }
  }
  return sum;
}

function doesContainB(a, b, c) {
    if (a === b) {
        return true;
    }
    if ((b - a) * c > 0 && (b - a) % c === 0) {
        return true;
    }
    return false;
}

function zigzag(n, k) {
    if (n === 0 && k === 0) {
        return 1;
    }
    if (k === 0) {
        return 0;
    }
    return zigzag(n, k - 1) + zigzag(n - 1, n - k);
}

function number_ctr(str) {
    let number_ctr = 0;
    for (let i = 0; i < str.length; i++) {
        if (str[i] >= '0' && str[i] <= '9') {
            number_ctr++;
        }
    }
    return number_ctr;
}

function lowerCtr(str) {
    let count = 0;
    for (let i = 0; i < str.length; i++) {
        if (str[i] >= 'a' && str[i] <= 'z') {
            count++;
        }
    }
    return count;
}

function sumDigitsSingle(x) {
    let ans = 0;
    while (x > 0) {
        ans += x % 10;
        x = Math.floor(x / 10);
    }
    return ans;
}

function closest(x) {
    let ans = 0;
    while (ans * 10 + 9 <= x) {
        ans = ans * 10 + 9;
    }
    return ans;
}

function sumDigitsTwoParts(N) {
    const A = closest(N);
    return sumDigitsSingle(A) + sumDigitsSingle(N - A);
}

function getNumber(n, k) {
  const arr = new Array(n);
  let i = 0;
  let odd = 1;
  while (odd <= n) {
    arr[i] = odd;
    i++;
    odd += 2;
  }
  let even = 2;
  while (even <= n) {
    arr[i] = even;
    i++;
    even += 2;
  }
  return arr[k - 1];
}

function countSubstrings(s, n) {
  let count = 0;
  let sum = 0;
  const mp = {};
  mp[0] = 1;
  for (let i = 0; i < n; i++) {
    sum += parseInt(s[i], 10);
    const key = sum - (i + 1);
    if (mp[key] === undefined) {
      mp[key] = 0;
    }
    count += mp[key];
    mp[key]++;
  }
  return count;
}

function oddDays(N) {
    const hund1 = Math.floor(N / 100);
    const hund4 = Math.floor(N / 400);
    let leap = Math.floor(N / 4);
    let ordd = N - leap;
    if (hund1) {
        ordd += hund1;
        leap -= hund1;
    }
    if (hund4) {
        ordd -= hund4;
        leap += hund4;
    }
    const days = ordd + leap * 2;
    return days % 7;
}

function isArmstrongNumber(number) {
    let sum = 0;
    let times = 0;
    let temp = number;
    while (temp > 0) {
        times++;
        temp = Math.floor(temp / 10);
    }
    temp = number;
    while (temp > 0) {
        const remainder = temp % 10;
        sum += remainder ** times;
        temp = Math.floor(temp / 10);
    }
    return number === sum;
}

function binCoff(n, r) {
  let val = 1;
  if (r > n - r) r = n - r;
  for (let i = 0; i < r; i++) {
    val *= (n - i);
    val = Math.floor(val / (i + 1));
  }
  return val;
}

function findWays(M) {
  const n = Math.floor(M / 2);
  const a = binCoff(2 * n, n);
  const b = Math.floor(a / (n + 1));
  return b;
}

function find_Diff(arr, n) {
    arr.sort((a, b) => a - b);
    let count = 0, max_count = 0, min_count = n;
    for (let i = 0; i < n - 1; i++) {
        if (arr[i] === arr[i + 1]) {
            count++;
            continue;
        } else {
            max_count = Math.max(max_count, count);
            min_count = Math.min(min_count, count);
            count = 0;
        }
    }
    return max_count - min_count;
}

function intToRoman(num) {
    const val = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
    const syb = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
    let romanNum = "";
    let i = 0;
    while (num > 0) {
        const count = Math.floor(num / val[i]);
        for (let j = 0; j < count; j++) {
            romanNum += syb[i];
            num -= val[i];
        }
        i++;
    }
    return romanNum;
}

function divSum(n) {
  let sum = 1;
  let i = 2;
  while (i * i <= n) {
    if (n % i === 0) {
      sum += i + Math.floor(n / i);
    }
    i++;
  }
  return sum;
}

function areEquivalent(num1, num2) {
  return divSum(num1) === divSum(num2);
}

function adjac(ele, sub = []) {
  if (ele.length === 0) {
    return [sub];
  } else {
    let results = [];
    for (let j = ele[0] - 1; j <= ele[0] + 1; j++) {
      results = results.concat(adjac(ele.slice(1), sub.concat(j)));
    }
    return results;
  }
}

function getCoordinates(testTup) {
  return adjac(testTup);
}

function countSetBits(n) {
    n += 1;
    let powerOf2 = 2;
    let cnt = Math.floor(n / 2);
    while (powerOf2 <= n) {
        const totalPairs = Math.floor(n / powerOf2);
        cnt += Math.floor(totalPairs / 2) * powerOf2;
        if (totalPairs & 1) {
            cnt += n % powerOf2;
        }
        powerOf2 <<= 1;
    }
    return cnt;
}

function maxSumSubseq(A) {
    const n = A.length;
    if (n === 1) {
        return A[0];
    }
    const lookUp = new Array(n);
    lookUp[0] = A[0];
    lookUp[1] = Math.max(A[0], A[1]);
    for (let i = 2; i < n; i++) {
        lookUp[i] = Math.max(lookUp[i - 1], lookUp[i - 2] + A[i]);
        lookUp[i] = Math.max(lookUp[i], A[i]);
    }
    return lookUp[n - 1];
}

function findGcd(x, y) {
  while (y !== 0) {
    [x, y] = [y, x % y];
  }
  return x;
}

function getGcd(arr) {
  let gcd = findGcd(arr[0], arr[1]);
  for (let i = 2; i < arr.length; i++) {
    gcd = findGcd(gcd, arr[i]);
  }
  return gcd;
}

function evenBitToggleNumber(n) {
    let res = 0;
    let count = 0;
    let temp = n;
    while (temp > 0) {
        if (count % 2 === 1) {
            res |= (1 << count);
        }
        count++;
        temp >>= 1;
    }
    return n ^ res;
}

function getPell(n) {
    if (n <= 2) {
        return n;
    }
    let a = 1;
    let b = 2;
    for (let i = 3; i <= n; i++) {
        const c = 2 * b + a;
        a = b;
        b = c;
    }
    return b;
}

function gcd(a, b) {
    while (b !== 0) {
        [a, b] = [b, a % b];
    }
    return a;
}

function minOperations(A, B) {
    if (A > B) {
        [A, B] = [B, A];
    }
    B = B / gcd(A, B);
    return B - 1;
}

function evenBitSetNumber(n) {
    let count = 0;
    let res = 0;
    let temp = n;
    while (temp > 0) {
        if (count % 2 === 1) {
            res |= (1 << count);
        }
        count++;
        temp >>= 1;
    }
    return n | res;
}

function babylonianSquareroot(number) {
    if (number === 0) {
        return 0;
    }
    let g = number / 2.0;
    let g2 = g + 1;
    while (g !== g2) {
        const n = number / g;
        g2 = g;
        g = (g + n) / 2;
    }
    return g;
}

function evenBitToggleNumber(n) {
    let res = 0;
    let count = 0;
    let temp = n;
    while (temp > 0) {
        if (count % 2 === 0) {
            res |= (1 << count);
        }
        count++;
        temp >>= 1;
    }
    return n ^ res;
}

function averageOdd(n) {
  if (n % 2 === 0) {
    return "Invalid Input";
  }
  let sm = 0;
  let count = 0;
  while (n >= 1) {
    count++;
    sm += n;
    n -= 2;
  }
  return Math.floor(sm / count);
}

function findMinSum(num) {
    let sum = 0;
    let i = 2;
    while (i * i <= num) {
        while (num % i === 0) {
            sum += i;
            num /= i;
        }
        i++;
    }
    sum += num;
    return sum;
}

function capitalizeFirstLastLetters(str) {
  return str
    .toLowerCase()
    .split(/\s+/)
    .map(word => {
      if (!word) return '';
      const first = word[0].toUpperCase();
      const middle = word.slice(1, -1);
      const last = word.length > 1 ? word[word.length - 1].toUpperCase() : '';
      return first + middle + last;
    })
    .join(' ');
}

function binomial_Coeff(n, k) {
    const C = new Array(k + 1).fill(0);
    C[0] = 1;
    for (let i = 1; i <= n; i++) {
        for (let j = Math.min(i, k); j > 0; j--) {
            C[j] += C[j - 1];
        }
    }
    return C[k];
}

function sum_Of_product(n) {
    return binomial_Coeff(2 * n, n - 1);
}

function averageEven(n) {
  if (n % 2 !== 0) {
    return "Invalid Input";
  }
  let sum = 0;
  let count = 0;
  while (n >= 2) {
    count++;
    sum += n;
    n -= 2;
  }
  return Math.floor(sum / count);
}

function getPosOfRightMostSetBit(n) {
    return Math.floor(Math.log2(n & -n) + 1);
}

function setRightMostUnsetBit(n) {
    if (n === 0) {
        return 1;
    }
    if ((n & (n + 1)) === 0) {
        return n;
    }
    const pos = getPosOfRightMostSetBit(~n);
    return (1 << (pos - 1)) | n;
}

function findFirstDuplicate(nums) {
  const numSet = new Set();
  const noDuplicate = -1;
  for (let i = 0; i < nums.length; i++) {
    if (numSet.has(nums[i])) {
      return nums[i];
    } else {
      numSet.add(nums[i]);
    }
  }
  return noDuplicate;
}

function getChar(strr) {
    let summ = 0;
    for (let i = 0; i < strr.length; i++) {
        summ += strr.charCodeAt(i) - 'a'.charCodeAt(0) + 1;
    }
    if (summ % 26 === 0) {
        return 'z';
    } else {
        summ = summ % 26;
        return String.fromCharCode('a'.charCodeAt(0) + summ - 1);
    }
}

function frequencyLists(list1) {
    const flattened = list1.flat();
    const dicData = {};
    for (const num of flattened) {
        if (dicData.hasOwnProperty(num)) {
            dicData[num] += 1;
        } else {
            dicData[num] = 1;
        }
    }
    return dicData;
}

function minOps(arr, n, k) {
    const max1 = Math.max(...arr);
    let res = 0;
    for (let i = 0; i < n; i++) {
        if ((max1 - arr[i]) % k !== 0) {
            return -1;
        } else {
            res += (max1 - arr[i]) / k;
        }
    }
    return res;
}

function setBitNumber(n) {
    if (n === 0) {
        return 0;
    }
    let msb = 0;
    n = Math.floor(n / 2);
    while (n > 0) {
        n = Math.floor(n / 2);
        msb++;
    }
    return 1 << msb;
}

function maxOccurrences(nums) {
    let maxVal = 0;
    let result = nums[0];
    for (const i of nums) {
        const occu = nums.filter(x => x === i).length;
        if (occu > maxVal) {
            maxVal = occu;
            result = i;
        }
    }
    return result;
}

function groupTuples(input) {
    const out = {};
    for (const elem of input) {
        const key = elem[0];
        if (out.hasOwnProperty(key)) {
            out[key].push(...elem.slice(1));
        } else {
            out[key] = elem.slice();
        }
    }
    return Object.values(out);
}

function moveNum(testStr) {
  let res = '';
  let dig = '';
  for (const ele of testStr) {
    if (/\d/.test(ele)) {
      dig += ele;
    } else {
      res += ele;
    }
  }
  return res + dig;
}

function maxOccurrences(list1) {
    let maxVal = 0;
    let result = list1[0];
    for (const i of list1) {
        const occu = list1.filter(item => item === i).length;
        if (occu > maxVal) {
            maxVal = occu;
            result = i;
        }
    }
    return result;
}

function removeDuplicate(string) {
  const words = string.split(/\s+/);
  const seen = new Set();
  const result = [];
  for (const word of words) {
    if (!seen.has(word)) {
      seen.add(word);
      result.push(word);
    }
  }
  return result.join(' ');
}

function equilibriumIndex(arr) {
  let totalSum = arr.reduce((acc, curr) => acc + curr, 0);
  let leftSum = 0;
  for (let i = 0; i < arr.length; i++) {
    totalSum -= arr[i];
    if (leftSum === totalSum) {
      return i;
    }
    leftSum += arr[i];
  }
  return -1;
}

function leftInsertion(a, x) {
  let lo = 0, hi = a.length;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (a[mid] < x) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo;
}

function rightInsertion(a, x) {
    let lo = 0, hi = a.length;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (x < a[mid]) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

function checkSubstring(string, sample) {
    if (string.includes(sample)) {
        const regex = new RegExp("^" + sample);
        if (regex.test(string)) {
            return "string starts with the given substring";
        } else {
            return "string doesnt start with the given substring";
        }
    } else {
        return "entered string isnt a substring";
    }
}

function lengthOfLastWord(a) {
    let l = 0;
    const x = a.trim();
    for (let i = 0; i < x.length; i++) {
        if (x[i] === ' ') {
            l = 0;
        } else {
            l++;
        }
    }
    return l;
}

function findRotations(str) {
    const tmp = str + str;
    const n = str.length;
    for (let i = 1; i <= n; i++) {
        const substring = tmp.slice(i, i + n);
        if (str === substring) {
            return i;
        }
    }
    return n;
}

function removeOcc(s, ch) {
    let firstIndex = s.indexOf(ch);
    if (firstIndex !== -1) {
        s = s.slice(0, firstIndex) + s.slice(firstIndex + 1);
    }
    let lastIndex = s.lastIndexOf(ch);
    if (lastIndex !== -1) {
        s = s.slice(0, lastIndex) + s.slice(lastIndex + 1);
    }
    return s;
}

