function oddBitSetNumber(n) {
    let count = 0, res = 0, temp = n;
    while (temp > 0) {
        if (count % 2 === 0) {
            res |= (1 << count);
        }
        count++;
        temp >>= 1;
    }
    return n | res;
}

function bellNumber(n) {
  const bell = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));
  bell[0][0] = 1;
  for (let i = 1; i <= n; i++) {
    bell[i][0] = bell[i - 1][i - 1];
    for (let j = 1; j <= i; j++) {
      bell[i][j] = bell[i - 1][j - 1] + bell[i][j - 1];
    }
  }
  return bell[n][0];
}

function first_Repeated_Char(str) {
    const h = {};
    for (const ch of str) {
        if (ch in h) {
            return ch;
        } else {
            h[ch] = 0;
        }
    }
    return '\0';
}

function findDemlo(s) {
  const l = s.length;
  let res = '';
  for (let i = 1; i <= l; i++) {
    res += i.toString();
  }
  for (let i = l - 1; i > 0; i--) {
    res += i.toString();
  }
  return res;
}

function countUnsetBits(n) {
    let count = 0;
    let x = 1;
    while (x < n + 1) {
        if ((x & n) === 0) {
            count++;
        }
        x <<= 1;
    }
    return count;
}

function charFrequency(str1) {
  const freq = {};
  for (const char of str1) {
    if (freq[char]) {
      freq[char] += 1;
    } else {
      freq[char] = 1;
    }
  }
  return freq;
}

function smallestMissing(A, leftElement, rightElement) {
    if (leftElement > rightElement) {
        return leftElement;
    }
    const mid = leftElement + Math.floor((rightElement - leftElement) / 2);
    if (A[mid] === mid) {
        return smallestMissing(A, mid + 1, rightElement);
    } else {
        return smallestMissing(A, leftElement, mid - 1);
    }
}

function breakSum(n) {
    const dp = new Array(n + 1).fill(0);
    if (n >= 1) dp[1] = 1;
    for (let i = 2; i <= n; i++) {
        dp[i] = Math.max(
            dp[Math.floor(i / 2)] + dp[Math.floor(i / 3)] + dp[Math.floor(i / 4)],
            i
        );
    }
    return dp[n];
}

function combinationsList(list1) {
  if (list1.length === 0) {
    return [[]];
  }
  const result = [];
  for (const el of combinationsList(list1.slice(1))) {
