}

function maxAbsDiff(arr, n) {
    let minEle = arr[0];
    let maxEle = arr[0];
    for (let i = 1; i < n; i++) {
        minEle = Math.min(minEle, arr[i]);
        maxEle = Math.max(maxEle, arr[i]);
    }
    return maxEle - minEle;
}

function gcd(p, q) {
    while (q !== 0) {
        [p, q] = [q, p % q];
    }
    return p;
}

function isCoprime(x, y) {
    return gcd(x, y) === 1;
}

function hammingDistance(n1, n2) {
    let x = n1 ^ n2;
    let setBits = 0;
    while (x > 0) {
        setBits += x & 1;
        x >>= 1;
    }
    return setBits;
}

function noOfTriangle(N, K) {
    if (N < K) {
        return -1;
    } else {
        const triUp = Math.floor((N - K + 1) * (N - K + 2) / 2);
        const triDown = Math.floor((N - 2 * K + 1) * (N - 2 * K + 2) / 2);
        return triUp + triDown;
    }
}

function countBinarySeq(n) {
    let nCr = 1;
    let res = 1;
    for (let r = 1; r <= n; r++) {
        nCr = nCr * (n + 1 - r) / r;
        res += nCr * nCr;
    }
    return res;
}

function sameOrder(l1, l2) {
  const set1 = new Set(l1);
  const set2 = new Set(l2);
  const common = new Set([...set1].filter(x => set2.has(x)));
  const filtered1 = l1.filter(e => common.has(e));
  const filtered2 = l2.filter(e => common.has(e));
  if (filtered1.length !== filtered2.length) return false;
  return filtered1.every((v, i) => v === filtered2[i]);
}

function jacobsthalLucas(n) {
    const dp = new Array(n + 1).fill(0);
    dp[0] = 2;
    dp[1] = 1;
    for (let i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + 2 * dp[i - 2];
    }
    return dp[n];
}

